  services: PantavionResilienceService[];
  recommendedActions: string[];
  evaluatedAt: string;
}

export interface PantavionResilienceRuntime {
  state: PantavionResilienceState;
  services: Map<string, PantavionResilienceService>;
  createResilienceState: typeof createResilienceState;
  evaluateResilience: typeof evaluateResilience;
  getResilienceSnapshot: typeof getResilienceSnapshot;
