  listServices: () => PantavionResilienceService[];
}

const pantavionResilienceServices = new Map<string, PantavionResilienceService>();

function normalizeServiceKey(service: PantavionResilienceService): string {
  return service.serviceKey || service.id || service.name || "pantavion.unknown.service";
}

function buildRecommendedActions(reasons: string[]): string[] {
  if (reasons.length === 0) {
    return ["continue_normal_operation"];
  }

  return Array.from(
    new Set(
      reasons.map((reason) =>
        reason.startsWith("service_")
          ? "inspect_" + reason
          : "handle_" + reason,
      ),
    ),
  );
}

export function createResilienceState(input: {
  mode?: PantavionResilienceMode;
  status?: PantavionResilienceMode;
  services?: PantavionResilienceService[];
  reasons?: string[];
  recommendedActions?: string[];
} = {}): PantavionResilienceState {
  const services = input.services ?? Array.from(pantavionResilienceServices.values());
  const reasons = input.reasons ?? [];
  const mode = input.mode ?? input.status ?? "normal";

  return {
    mode,
    status: input.status ?? mode,
    services,
    updatedAt: new Date().toISOString(),
    reasons,
    recommendedActions: input.recommendedActions ?? buildRecommendedActions(reasons),
  };
}

export function evaluateResilience(input: {
  requestedServices?: string[];
  requiresWorkspaceContinuity?: boolean;
  requiresVoiceContinuity?: boolean;
  reasons?: string[];
} = {}): PantavionResilienceEvaluation {
  const requestedServices = input.requestedServices ?? [];
  const reasons = [...(input.reasons ?? [])];

  for (const serviceKey of requestedServices) {
    const service = pantavionResilienceServices.get(serviceKey);

    if (!service) {
      reasons.push("service_missing_" + serviceKey);
      continue;
    }

    if (service.status === "failed") {
      reasons.push("service_failed_" + serviceKey);
    }

    if (service.status === "degraded") {
      reasons.push("service_degraded_" + serviceKey);
    }
  }

  if (input.requiresWorkspaceContinuity) {
    reasons.push("workspace_continuity_required");
  }

  if (input.requiresVoiceContinuity) {
    reasons.push("voice_continuity_required");
  }

  const mode: PantavionResilienceMode =
    reasons.some((reason) => reason.includes("failed"))
      ? "fallback"
      : reasons.length > 0
        ? "protected"
        : "normal";

  return {
    mode,
    status: mode,
    reasons,
    requestedServices,
    requiresWorkspaceContinuity: input.requiresWorkspaceContinuity ?? false,
    requiresVoiceContinuity: input.requiresVoiceContinuity ?? false,
    recommendedActions: buildRecommendedActions(reasons),
    evaluatedAt: new Date().toISOString(),
  };
}

export function getResilienceSnapshot(): PantavionResilienceSnapshot {
  const services = Array.from(pantavionResilienceServices.values());
  const failedServices = services.filter((service) => service.status === "failed");
  const degradedServices = services.filter((service) => service.status === "degraded");

  const reasons = [
    ...failedServices.map((service) => "service_failed_" + normalizeServiceKey(service)),
    ...degradedServices.map((service) => "service_degraded_" + normalizeServiceKey(service)),
  ];

  const mode: PantavionResilienceMode =
    failedServices.length > 0
      ? "fallback"
      : degradedServices.length > 0
        ? "degraded"
        : "normal";

  const state = createResilienceState({
    mode,
    status: mode,
    services,
    reasons,
    recommendedActions: buildRecommendedActions(reasons),
  });

  return {
    mode,
    status: mode,
    state,
    services,
    recommendedActions: state.recommendedActions,
    evaluatedAt: state.updatedAt,
  };
}

