function normalizeInterfaceRationale(interfaceStartText) {
  const start = lines.findIndex((line) => line.includes(interfaceStartText));
  if (start === -1) {
    throw new Error("Interface not found: " + interfaceStartText);
  }

  let end = -1;
  for (let i = start + 1; i < lines.length; i += 1) {
