      break;
    }
  }

  if (end === -1) {
    throw new Error("Interface end not found: " + interfaceStartText);
  }

  const before = lines.slice(0, start + 1);
  const body = lines
    .slice(start + 1, end)
    .filter((line) => line.trim() !== "rationale?: string[];");
  const after = lines.slice(end);

  body.push("  rationale?: string[];");

  lines = [...before, ...body, ...after];
}

