} from "../../types/pantavion";

export type PantavionTrustTier =
  | "anonymous"
  | "unverified"
  | "trusted"
  | "high-trust"
  | "system"
  | string;

export type PantavionApprovalTier =
  | "none"
  | "review"
  | "admin"
  | "security"
  | "system"
  | string;

export interface PantavionAuthorityProof {
  id: string;
  kind: "direct" | "delegated" | "service" | "system";
  issuedAt: string;
  expiresAt?: string;
  issuedBy?: string;
  note?: string;
}

export interface PantavionIdentityProfile {
  id: string;
  type: PantavionPrincipalType;
  displayName: string;
  region?: string;
  sensitivityCeiling: PantavionSensitivity;
  roles: string[];
  scopes: PantavionScope[];
  active: boolean;
  verified: boolean;
  primaryRole?: string;
  trustTier?: PantavionTrustTier;
  approvalTier?: PantavionApprovalTier;
  status?: string;
  metadata?: Record<string, unknown>;
}

export interface PantavionIdentityResolution {
  actor: PantavionIdentityProfile;
  proofs: PantavionAuthorityProof[];
  effectiveRoles: string[];
  effectiveScopes: PantavionScope[];
  approved: boolean;
  denialReasons: string[];
}

export type PantavionIdentityInput = PantavionActorRef & {
  actorId?: string;
  actorType?: PantavionPrincipalType;
  role?: string;
  primaryRole?: string;
  trustTier?: PantavionTrustTier;
  trustTierHint?: PantavionTrustTier;
  approvalTier?: PantavionApprovalTier;
  status?: string;
  defaultScopes?: Array<PantavionScope | { kind?: string; id?: string; label?: string }>;
  delegatedBy?: string;
  workspaceId?: string;
  orgId?: string;
  planKey?: string;
  requestedOperation?: string;
  requestedSensitivity?: PantavionSensitivity;
  sensitivityCeiling?: PantavionSensitivity;
  metadata?: Record<string, unknown>;
};

const VALID_SCOPES = new Set<string>([
  "read",
  "write",
  "execute",
  "delegate",
  "approve",
  "admin",
  "memory",
  "policy",
  "identity",
  "ops",
  "protocol",
]);

export const SYSTEM_KERNEL_IDENTITY: PantavionIdentityProfile = {
  id: "pantavion.kernel0",
  type: "system",
  displayName: "Pantavion Kernel 0",
  sensitivityCeiling: "critical",
  roles: ["kernel", "governor", "system"],
  scopes: ["read", "write", "execute", "delegate", "approve", "admin", "memory", "policy", "identity", "ops", "protocol"],
  active: true,
  verified: true,
  primaryRole: "system-runtime",
  trustTier: "system",
  approvalTier: "security",
  status: "active",
};

function normalizeScope(value: PantavionScope | { kind?: string; id?: string; label?: string }): PantavionScope {
  if (typeof value === "string") {
    return value as PantavionScope;
  }

  const candidate = value.kind || value.id || "read";

  if (VALID_SCOPES.has(candidate)) {
    return candidate as PantavionScope;
  }

  return "read";
}

function uniqueStrings(values: string[]): string[] {
  return Array.from(new Set(values.filter((value) => value.trim().length > 0)));
}

function uniqueScopes(values: PantavionScope[]): PantavionScope[] {
  return Array.from(new Set(values));
}

export function buildIdentityProfile(actor: PantavionIdentityInput): PantavionIdentityProfile {
  const id = actor.id || actor.actorId || "unknown-actor";
  const type = actor.type || actor.actorType || "human";
  const primaryRole = actor.primaryRole || actor.role;
  const roles = uniqueStrings([...(actor.roles ?? []), ...(primaryRole ? [primaryRole] : [])]);

  const rawScopes = actor.scopes ?? actor.defaultScopes ?? ["read"];
  const scopes = uniqueScopes(rawScopes.map((scope) => normalizeScope(scope)));

  const metadata = {
    ...(actor.metadata ?? {}),
    delegatedBy: actor.delegatedBy,
    workspaceId: actor.workspaceId,
    orgId: actor.orgId,
    planKey: actor.planKey,
    requestedOperation: actor.requestedOperation,
  };

  return {
    id,
    type,
    displayName: actor.displayName ?? id,
    region: actor.region,
    sensitivityCeiling: actor.sensitivityCeiling ?? actor.requestedSensitivity ?? "internal",
    roles,
    scopes,
    active: actor.status ? actor.status !== "disabled" && actor.status !== "inactive" : true,
    verified: actor.verified ?? type === "system" ?? false,
    primaryRole,
    trustTier: actor.trustTier ?? actor.trustTierHint,
    approvalTier: actor.approvalTier,
    status: actor.status ?? "active",
    metadata,
  };
}

export function resolveIdentity(
  actor: PantavionIdentityInput | undefined,
  proofs: PantavionAuthorityProof[] = [],
): PantavionIdentityResolution {
  const profile = buildIdentityProfile(actor ?? { id: "unknown-actor", verified: false });

  const denialReasons: string[] = [];
  if (!profile.id.trim()) denialReasons.push("missing_actor_id");
  if (!profile.active) denialReasons.push("actor_inactive");
  if (!profile.verified) denialReasons.push("actor_unverified");

  return {
    actor: profile,
    proofs,
    effectiveRoles: uniqueStrings(profile.roles),
    effectiveScopes: uniqueScopes(profile.scopes),
    approved: denialReasons.length === 0,
    denialReasons,
  };
}

export function hasRequiredScopes(
  resolution: PantavionIdentityResolution,
  requiredScopes: PantavionScope[],
): boolean {
  return requiredScopes.every((scope) => resolution.effectiveScopes.includes(scope));
}

export function registerIdentity(actor: PantavionIdentityInput): PantavionIdentityProfile {
  return buildIdentityProfile(actor);
}

export function resolveIdentityPosture(
  actor: PantavionIdentityInput | undefined,
  proofs: PantavionAuthorityProof[] = [],
): PantavionIdentityResolution {
  return resolveIdentity(actor, proofs);
}

