const RECOVERY_PREFIX = "water/private/recovery-requests/";
const AUDIT_PREFIX = "water/private/access-audit/";

function clean(value: unknown) {
  return typeof value === "string" ? value.trim().slice(0, 500) : "";
}

export function normalizeWaterContact(value: unknown) {
  return clean(value).toLowerCase().replace(/[\s().-]/g, "");
}

function safeKey(value: string) {
  return value.replace(/[^a-zA-Z0-9_-]/g, "_").slice(0, 120) || "unknown";
}

function nowIso() {
  return new Date().toISOString();
}

function blobHeaders(): HeadersInit | undefined {
  const token = [REDACTED]
  return token ? { Authorization: `Bearer ${token}` } : undefined;
}

async function readJsonFromBlob<T>(url: string): Promise<T | null> {
  try {
    const response = await fetch(url, {
      cache: "no-store",
      headers: blobHeaders(),
    });

    if (!response.ok) return null;

    return (await response.json()) as T;
  } catch {
    return null;
  }
}

async function listJsonRecords<T>(prefix: string): Promise<T[]> {
  const result = await list({ prefix });
  const records: T[] = [];

  for (const blob of result.blobs) {
    if (!blob.pathname.endsWith(".json")) continue;

    const blobLike = blob as typeof blob & { downloadUrl?: string };
    const url = blobLike.downloadUrl || blob.url;
    const json = await readJsonFromBlob<T>(url);

    if (json) records.push(json);
  }

  return records;
}

async function writeJson(pathname: string, value: unknown) {
  await put(pathname, JSON.stringify(value, null, 2), {
    access: "private",
    allowOverwrite: true,
    contentType: "application/json",
  });
}

export async function listWaterAccessRequests() {
  const records = await listJsonRecords<WaterAccessRequest>(ACCESS_REQUEST_PREFIX);
  return records.sort((a, b) => b.createdAt.localeCompare(a.createdAt));
}

export async function listApprovedWaterUsers() {
  const records = await listJsonRecords<ApprovedWaterUser>(APPROVED_USERS_PREFIX);
  return records.sort((a, b) => b.approvedAt.localeCompare(a.approvedAt));
}

export async function listWaterRecoveryRequests() {
  const records = await listJsonRecords<WaterRecoveryRequest>(RECOVERY_PREFIX);
  return records.sort((a, b) => b.createdAt.localeCompare(a.createdAt));
}

export async function listWaterAccessAudit() {
  const records = await listJsonRecords<WaterAccessAuditRecord>(AUDIT_PREFIX);
  return records.sort((a, b) => b.createdAt.localeCompare(a.createdAt)).slice(0, 100);
}

export async function writeWaterAccessAudit(
  event: WaterAccessAuditRecord["event"],
  payload: Record<string, unknown>,
) {
  const record: WaterAccessAuditRecord = {
    id: `water-audit-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    event,
    actor: "founder",
    createdAt: nowIso(),
    payload,
  };

  await writeJson(`${AUDIT_PREFIX}${record.id}.json`, record);

  return record;
}

function accessUntilFor(kind: "two_hours" | "today" | "permanent") {
  if (kind === "permanent") return null;

  const date = new Date();

  if (kind === "two_hours") {
    date.setHours(date.getHours() + 2);
    return date.toISOString();
  }

  date.setHours(23, 59, 59, 999);
  return date.toISOString();
}

export async function approveWaterAccessRequest(
  requestId: string,
  kind: "two_hours" | "today" | "permanent",
) {
  const requests = await listWaterAccessRequests();
  const request = requests.find((item) => item.id === requestId);

  if (!request) throw new Error("request_not_found");

  const approved: ApprovedWaterUser = {
    id: `approved-${safeKey(normalizeWaterContact(request.emailOrPhone) || request.id)}`,
    requestId: request.id,
    firstName: request.firstName,
    lastName: request.lastName,
    title: request.title,
    organization: request.organization,
    emailOrPhone: request.emailOrPhone,
    approvedAt: nowIso(),
    approvedBy: "founder",
    permanent: kind === "permanent",
    accessUntil: accessUntilFor(kind),
    revoked: false,
    scope: {
      module: "water",
      layer: "mobile_water_network",
      exportAllowed: false,
      downloadKmzAllowed: false,
    },
  };

  const updatedRequest: WaterAccessRequest = {
    ...request,
    status: "approved",
    updatedAt: nowIso(),
  };

  await writeJson(`${ACCESS_REQUEST_PREFIX}${request.id}.json`, updatedRequest);
  await writeJson(`${APPROVED_USERS_PREFIX}${approved.id}.json`, approved);
  await writeWater

