"use client";

import { useState } from "react";

export default function WaterRecoverPage() {
  const [firstName, setFirstName] = useState("");
  const [lastName, setLastName] = useState("");
  const [emailOrPhone, setEmailOrPhone] = useState("");
  const [note, setNote] = useState("");
  const [message, setMessage] = useState("Συμπλήρωσε τα στοιχεία σου για ανάκτηση πρόσβασης.");

  async function submitRecovery() {
    setMessage("Αποστολή αιτήματος ανάκτησης...");

    try {
      const response = await fetch("/api/professional/infrastructure/water/access/recover", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ firstName, lastName, emailOrPhone, note }),
      });

      const json = await response.json();

      if (!response.ok || !json.ok) {
        setMessage("Δεν στάλθηκε η αίτηση ανάκτησης.");
        return;
      }

      setMessage("Η αίτηση ανάκτησης στάλθηκε στον Founder για έλεγχο.");
    } catch {
      setMessage("Δεν στάλθηκε η αίτηση ανάκτησης.");
    }
  }

  return (
    <main className="min-h-screen bg-[#06111f] px-4 py-8 text-white">
      <section className="mx-auto max-w-2xl rounded-3xl border border-[#d8b35a]/25 bg-[#101b2f] p-6">
        <p className="text-xs font-black uppercase tracking-[0.28em] text-[#d8b35a]">
          Pantavion Water Access
        </p>

        <h1 className="mt-3 text-4xl font-black">Ανάκτηση πρόσβασης</h1>

        <p className="mt-4 text-slate-200">
          Αν δεν θυμάσαι τα στοιχεία πρόσβασης, στείλε αίτημα στον Founder.
          Δεν ανοίγει αυτόματα ο χάρτης χωρίς έγκριση.
        </p>

        <div className="mt-6 grid gap-3">
          <input value={firstName} onChange={(event) => setFirstName(event.target.value)} placeholder="Όνομα" className="rounded-2xl border border-white/15 bg-[#07111f] px-4 py-3 text-white" />
          <input value={lastName} onChange={(event) => setLastName(event.target.value)} placeholder="Επίθετο" className="rounded-2xl border border-white/15 bg-[#07111f] px-4 py-3 text-white" />
          <input value={emailOrPhone} onChange={(event) => setEmailOrPhone(event.target.value)} placeholder="Τηλέφωνο ή email" className="rounded-2xl border border-white/15 bg-[#07111f] px-4 py-3 text-white" />
          <textarea value={note} onChange={(event) => setNote(event.target.value)} placeholder="Σημείωση / ρόλος / οργανισμός" className="min-h-28 rounded-2xl border border-white/15 bg-[#07111f] px-4 py-3 text-white" />
        </div>

        <div className="mt-5 flex flex-wrap gap-3">
          <button type="button" onClick={submitRecovery} className="rounded-2xl border border-[#d8b35a]/40 bg-[#d8b35a]/15 px-5 py-3 text-sm font-bold text-[#ffe8a3]">
            Αποστολή ανάκτησης
          </button>

          <a href="/professional/infrastructure/water" className="rounded-2xl border border-white/15 bg-white/10 px-5 py-3 text-sm font-bold text-white">
            Πίσω στην πρόσβαση
          </a>
        </div>

        <p className="mt-5 text-sm font-bold text-[#ffe8a3]">{message}</p>
      </section>
    </main>
  );
}

