      "Offline success must not be confused with cloud sync success.",
      "Emergency surfaces must not promise impossible guarantees."
    ]
  }
];

export function getArchitectureLayer(id: string): ArchitectureLayer | undefined {
  return pantavionArchitectureLayers.find((layer) => layer.id === id);
}

export function architectureStatusLabel(status: ArchitectureLayerStatus): string {
  switch (status) {
    case "foundation":
      return "Foundation";
    case "active_build":
      return "Active Build";
    case "next_phase":
      return "Next Phase";
    case "later_scale":
      return "Later Scale";
    default:
      return status;
  }
}

export function architectureStatusClass(status: ArchitectureLayerStatus): string {
  switch (status) {
    case "foundation":
      return "border-emerald-400/30 bg-emerald-500/10 text-emerald-200";
    case "active_build":
      return "border-[#d4af37]/30 bg-[#d4af37]/10 text-[#f3d36b]";
    case "next_phase":
      return "border-sky-400/30 bg-sky-500/10 text-sky-200";
    case "later_scale":
      return "border-white/15 bg-white/5 text-white/65";
    default:
      return "border-white/15 bg-white/5 text-white/65";
  }
}

