import type {
  ApprovalItem,
  BuildHealthReport,
  ControlRoomSnapshot,
  RepoFinding,
} from '../runtime-types';

export function createControlRoomSnapshot(input: {
  approvals: ApprovalItem[];
  findings: RepoFinding[];
  build: BuildHealthReport;
}): ControlRoomSnapshot {
  const criticalFindings = input.findings.filter((item) => item.severity === 'critical').length;
  const blockingBuilds = input.build.buildPassed && input.build.typecheckPassed && input.build.blockers.length === 0 ? 0 : 1;

  return {
    generatedAt: new Date().toISOString(),
    openApprovals: input.approvals.filter((item) => item.required).length,
    criticalFindings,
    blockingBuilds,
    summary: blockingBuilds || criticalFindings
      ? 'Control room reports blocking conditions.'
      : 'Control room reports stable baseline.',
  };
}

import type { BuildHealthReport, RuntimeJobEnvelope, RuntimeJobResult } from '../runtime-types';

export interface BuildGuardianPayload {
  buildPassed: boolean;
  typecheckPassed: boolean;
  warnings?: string[];
  blockers?: string[];
}

export type BuildGuardianJob = RuntimeJobEnvelope<BuildGuardianPayload>;

export function summarizeBuildHealth(job: BuildGuardianJob): RuntimeJobResult<BuildHealthReport> {
  const report: BuildHealthReport = {
    buildPassed: job.payload.buildPassed,
    typecheckPassed: job.payload.typecheckPassed,
    warnings: job.payload.warnings ?? [],
    blockers: job.payload.blockers ?? [],
  };

  const healthy = report.buildPassed && report.typecheckPassed && report.blockers.length === 0;

  return {
    jobId: job.id,
    status: healthy ? 'completed' : 'blocked',
    summary: healthy ? 'Build guardian reports healthy repository state.' : 'Build guardian detected blocking repository state.',
    result: report,
    blockers: report.blockers,
    warnings: report.warnings,
  };
}

import type { ApprovalItem, RuntimeJobEnvelope, RuntimeJobResult } from '../runtime-types';

export interface ApprovalInboxPayload {
  items: ApprovalItem[];
}

export type ApprovalInboxJob = RuntimeJobEnvelope<ApprovalInboxPayload>;

export function queueApprovals(job: ApprovalInboxJob): RuntimeJobResult<ApprovalItem[]> {
  const requiredItems = job.payload.items.filter((item) => item.required);

  return {
    jobId: job.id,
    status: requiredItems.length ? 'blocked' : 'completed',
    summary: requiredItems.length
      ? 'Approval inbox has required blocking approvals.'
      : 'Approval inbox has no blocking approvals.',
    result: job.payload.items,
    blockers: requiredItems.map((item) => item.id),
    warnings: job.payload.items.filter((item) => !item.required).map((item) => item.id),
  };
}

