const LEDGER_PATH = path.join(process.cwd(), "pantavion-kernel-ledger.json");

export interface KernelLedgerRecord {
  id: string;
  createdAt: string;
  mission: any;
  status: string;
  verifier: any;
  finalDecision: string;
  taskGraph: any[];
  missing: string[];
  repairs: any[];
}

function ensureLedgerFile() {
  if (!fs.existsSync(LEDGER_PATH)) {
    fs.writeFileSync(LEDGER_PATH, "[]", "utf-8");
  }
}

export function readKernelLedger(): KernelLedgerRecord[] {
  ensureLedgerFile();
  try {
    const raw = fs.readFileSync(LEDGER_PATH, "utf-8");
    return JSON.parse(raw);
  } catch {
    return [];
  }
}

export function appendKernelLedger(record: KernelLedgerRecord) {
  const current = readKernelLedger();
  current.push(record);
  fs.writeFileSync(LEDGER_PATH, JSON.stringify(current, null, 2), "utf-8");
  return record;
}

﻿import { createPlan } from "./pantavion-planner";
import { runPlan } from "./pantavion-runner";
import { addMemory } from "./pantavion-memory";

export function kernelExecute(input: string) {
  addMemory("directive", input);

  const plan = createPlan(input);
  const results = runPlan(plan);

  addMemory("task", JSON.stringify(results));

  return {
    input,
    plan,
    results
  };
}

﻿export type MemoryType =
  | "directive"
  | "decision"
  | "task"
  | "module"
  | "system"
  | "user"
  | "signal";

export type MemoryEntry = {
  id: string;
  type: MemoryType;
  content: string;
  createdAt: string;
};

const MEMORY: MemoryEntry[] = [];

function now() {
  return new Date().toISOString();
}

export function addMemory(type: MemoryType, content: string) {
  const entry: MemoryEntry = {
    id: Date.now().toString(),
    type,
    content,
    createdAt: now()
  };

  MEMORY.unshift(entry);
  return entry;
}

export function getMemory() {
  return MEMORY;
}

﻿export function createPlan(input: string) {
  const plan = [];

  if (input.includes("build") || input.includes("χτίσε")) {
    plan.push("analyze request");
    plan.push("define modules");
    plan.push("create file structure");
    plan.push("generate code");
    plan.push("validate");
  }

  if (input.includes("voice")) {
    plan.push("setup voice engine");
  }

  if (input.includes("app")) {
    plan.push("setup backend");
    plan.push("setup frontend");
  }

  return plan;
}

﻿export function runPlan(plan: string[]) {
  const results = [];

  for (const step of plan) {
    results.push(`Executed: ${step}`);
  }

  return results;
}

