  try {
    const parsed = JSON.parse(readFileSync(vercelProjectJson, 'utf8')) as PantavionLinkedVercelProjectInfo;
    return {
      projectId: parsed.projectId,
      orgId: parsed.orgId,
      projectName: parsed.projectName,
    };
  } catch {
    return null;
  }
