  | 'custom';

export type PantavionPreparationStatus =
  | 'queued'
  | 'running'
  | 'ready'
  | 'completed'
  | 'blocked'
  | 'cancelled';

export interface PantavionBackgroundPreparationJob {
  preparationJobId: string;
  userId: string;
  threadId: string;
  linkedCommitmentId?: string;
  queuedAt: string;
  plannedFor?: string;
  preparationType: PantavionPreparationType;
  title: string;
