      unresolvedCount: list.filter((item) => item.resolutionState !== 'resolved').length,
      resolvedCount: list.filter((item) => item.resolutionState === 'resolved').length,
      latestThreadId: list[0]?.threadId,
    };
  }

  clear(): void {
    this.threads.clear();
  }
}

