  return {
    generatedAt: nowIso(),
    railCount: rails.length,
    activeRailCount: rails.filter((item) => item.status === 'active').length,
    recurringPlanCount: plans.filter(
      (item) => item.interval === 'monthly' || item.interval === 'annual',
