type WaterCollection = {
  type: "FeatureCollection";
  features: unknown[];
  pantavion?: Record<string, unknown>;
};

export type CloudWaterNetworkResult = {
  ok: boolean;
  sourceMode:
    | "production_cloud"
    | "local_private_file"
    | "not_configured"
    | "error";
  sourceConfigured: boolean;
  sourceLabel: string;
  error?: string;
  errorMessage?: string;
  raw?: string;
  collection: WaterCollection;
  features: unknown[];
  featureCount: number;
  returnedFeatureCount: number;
};

const emptyCollection: WaterCollection = {
  type: "FeatureCollection",
  features: [],
  pantavion: {},
};

function failureResult(
  sourceMode: CloudWaterNetworkResult["sourceMode"],
  sourceConfigured: boolean,
  sourceLabel: string,
  message: string,
): CloudWaterNetworkResult {
  return {
    ok: false,
    sourceMode,
    sourceConfigured,
    sourceLabel,
    error: message,
    errorMessage: message,
    collection: emptyCollection,
    features: [],
    featureCount: 0,
    returnedFeatureCount: 0,
  };
}

export async function readCloudWaterNetworkSource(): Promise<CloudWaterNetworkResult> {
  const url = process.env.PANTAVION_WATER_NETWORK_GEOJSON_URL;
  const token = [REDACTED]

  if (!url) {
    return failureResult(
      "not_configured",
      false,
      "not_configured",
      "PANTAVION_WATER_NETWORK_GEOJSON_URL is not configured.",
    );
  }

  if (!token) {
    return failureResult(
      "error",
      true,
      "missing_blob_token",
      "BLOB_READ_WRITE_TOKEN is not configured.",
    );
  }

  try {
    const result = await get(url, {
      access: "private",
      token,
    });

    if (!result?.stream) {
      return failureResult(
        "error",
        true,
        "invalid_blob_stream",
        "Private blob source returned no readable stream.",
      );
    }

    const raw = await new Response(result.stream).text();
    const parsed = JSON.parse(raw);
    const features = Array.isArray(parsed?.features) ? parsed.features : [];

    const collection: WaterCollection = {
      type: "FeatureCollection",
      ...parsed,
      features,
      pantavion:
        parsed && typeof parsed.pantavion === "object" && parsed.pantavion !== null
          ? parsed.pantavion
          : {},
    };

    return {
      ok: true,
      sourceMode: "production_cloud",
      sourceConfigured: true,
      sourceLabel: "vercel_blob_private",
      raw,
      collection,
      features,
      featureCount: features.length,
      returnedFeatureCount: features.length,
    };
  } catch (error) {
    const message =
      error instanceof Error
        ? error.message
        : "Unknown cloud water network source error.";

    return failureResult("error", true, "cloud_read_error", message);
  }
}

export async function readWaterNetworkSource(): Promise<CloudWaterNetworkResult> {
  return readCloudWaterNetworkSource();
}

export function getWaterNetworkGeometrySummary(features?: unknown[]) {
  return {
    featureCount: Array.isArray(features) ? features.length : 0,
    returnedFeatureCount: Array.isArray(features) ? features.length : 0,
  };
}

export function selectWaterNetworkMapFeatures(
  features?: unknown[],
  limit?: number,
) {
  const safeFeatures = Array.isArray(features) ? features : [];

  if (typeof limit !== "number" || !Number.isFinite(limit) || limit <= 0) {
    return safeFeatures;
  }

  return safeFeatures.slice(0, limit);
}

﻿import {
  isAuthorizedWaterPerson,
  type PantavionWaterAuthorizedPerson,
} from "./water-serving-contract";

export const PANTAVION_WATER_CONTROLLED_ACCESS_VERSION =
  "water-controlled-access-v1" as const;

export type PantavionWaterControlledAccessMode =
  | "denied"
  | "viewer"
  | "operator"
  | "admin"
  | "founder-admin";

export interface PantavionWaterAccessDecision {
  allowed: boolean;
  mode: PantavionWaterControlledAccessMode;
  blockers: string[];
  mayViewControlledNetwork: boolean;
  mayViewFullControlledFounderScope: boolean;
  mayExportRawNetwork: false;
}

function normalizeAccessLevel(accessLevel: string): string {
  return accessLevel.trim().toLowerCase();
}

export function evaluateControlledWaterAccess(
  person: PantavionWaterAuthorizedPerson,
): PantavionWaterAccessDecision {
  const blockers: string[] = [];

  if (!isAuthorizedWaterPerson(person)) {
    blockers.push(
      "Authorized water access requires first name, last name, title, access level, and active status.",
    );
  }

  if (person.status === "inactive") {
    blockers.push("Water access is inactive.");
  }

  if (person.status === "revoked") {
    blockers.push("Water access is revoked.");
  }

  const accessLevel = normalizeAccessLevel(person.accessLevel);

  const isFounderAdmin =
    accessLevel === "founder-admin" ||
    accessLevel === "founder-admin-diagnostic" ||
    accessLevel === "founder" ||
    accessLevel === "admin-owner";

  const isAdmin = isFounderAdmin || accessLevel === "admin" || accessLevel === "network-admin";
  const isOperator = isAdmin || accessLevel === "operator" || accessLevel === "field-operator";
  const isViewer = isOperator || accessLevel === "viewer" || accessLevel === "read-only";

  if (!isViewer) {
    blockers.push("Water access level is not permitted.");
  }

  if (blockers.length > 0) {
    return {
      allowed: false,
      mode: "denied",
      blockers,
      mayViewControlledNetwork: false,
      mayViewFullControlledFounderScope: false,
      mayExportRawNetwork: false,
    };
  }

  return {
    allowed: true,
    mode: isFounderAdmin ? "founder-admin" : isAdmin ? "admin" : isOperator ? "operator" : "viewer",
    blockers: [],
    mayViewControlledNetwork: true,
    mayViewFullControlledFounderScope: isFounderAdmin,
    mayExportRawNetwork: false,
  };
}

