export const SOS_CONFIG = {
  MAX_CONTACTS: 3,
  CONTACT_TIMEOUT_MS: 20_000,
}

import { SosSession, SosState } from './sos.types'
import { SOS_CONFIG } from './sos.config'

let timer: ReturnType<typeof setTimeout> | null = null

export function startSosSession(): SosSession {
  return {
    currentState: SosState.TRIGGERED,
    activeContactIndex: 0,
    startedAt: Date.now(),
    logs: [
      {
        state: SosState.TRIGGERED,
        timestamp: Date.now(),
        note: 'SOS Activated',
      },
    ],
  }
}

export function escalate(
  session: SosSession,
  onUpdate: (s: SosSession) => void
) {
  clear()

  if (session.activeContactIndex >= SOS_CONFIG.MAX_CONTACTS) {
    session.currentState = SosState.COMPLETE
    log(session, SosState.COMPLETE, 'All contacts exhausted')
    onUpdate({ ...session })
    return
  }

  const pendingStates = [
    SosState.CONTACT_1_PENDING,
    SosState.CONTACT_2_PENDING,
    SosState.CONTACT_3_PENDING,
  ]

  const state = pendingStates[session.activeContactIndex]
  session.currentState = state
  log(session, state, `Contact ${session.activeContactIndex + 1}`)
  onUpdate({ ...session })

  timer = setTimeout(() => {
    session.activeContactIndex++
    escalate(session, onUpdate)
  }, SOS_CONFIG.CONTACT_TIMEOUT_MS)
}

export function acknowledge(
  session: SosSession,
  onUpdate: (s: SosSession) => void
) {
  clear()

  const ackStates = [
    SosState.CONTACT_1_ACK,
    SosState.CONTACT_2_ACK,
    SosState.CONTACT_3_ACK,
  ]

  const state = ackStates[session.activeContactIndex]
  session.currentState = state
  log(session, state, 'Acknowledged')
  onUpdate({ ...session })
}

export function cancelSos(
  session: SosSession,
  onUpdate: (s: SosSession) => void
) {
  clear()
  session.currentState = SosState.CANCELLED
  log(session, SosState.CANCELLED, 'Cancelled')
  onUpdate({ ...session })
}

function log(session: SosSession, state: SosState, note?: string) {
  session.logs.push({ state, timestamp: Date.now(), note })
}

function clear() {
  if (timer) {
    clearTimeout(timer)
    timer = null
  }
}

import { create } from 'zustand'
import { SosSession } from './sos.types'
import {
  startSosSession,
  escalate,
  cancelSos,
  acknowledge,
} from './sos.engine'

type SosStore = {
  session: SosSession | null
  start: () => void
  cancel: () => void
  ack: () => void
}

export const useSosStore = create<SosStore>((set, get) => ({
  session: null,

  start: () => {
    const session = startSosSession()
    set({ session })
    escalate(session, (s) => set({ session: s }))
  },

  cancel: () => {
    const session = get().session
    if (!session) return
    cancelSos(session, (s) => set({ session: s }))
  },

  ack: () => {
    const session = get().session
    if (!session) return
    acknowledge(session, (s) => set({ session: s }))
  },
}))

