import { NextRequest, NextResponse } from "next/server";
import crypto from "crypto";

const WEBHOOK_SECRET = [REDACTED] || "";

/**
 * Verify Lemon Squeezy webhook signature
 */
function verifySignature(rawBody: string, signature: string) {
  if (!WEBHOOK_SECRET) return false;

  const hmac = crypto
    .createHmac("sha256", WEBHOOK_SECRET)
    .update(rawBody, "utf8")
    .digest("hex");

  return crypto.timingSafeEqual(
    Buffer.from(hmac),
    Buffer.from(signature || "", "utf8")
  );
}

export async function POST(req: NextRequest) {
  try {
    const signature = req.headers.get("X-Signature") || "";
    const rawBody = await req.text();

    // 1️⃣ Verify signature
    const isValid = verifySignature(rawBody, signature);
    if (!isValid) {
      return NextResponse.json(
        { error: "Invalid signature" },
        { status: 401 }
      );
    }

    // 2️⃣ Parse payload
    const payload = JSON.parse(rawBody);

    const eventName = payload?.meta?.event_name;
    const data = payload?.data;

    // We only care about successful orders for now
    if (eventName !== "order_created") {
      return NextResponse.json({ received: true });
    }

    const email =
      data?.attributes?.user_email ||
      data?.attributes?.customer_email ||
      null;

    const productName = data?.attributes?.first_order_item?.product_name;
    const total = data?.attributes?.total_formatted;

    // 3️⃣ TODO: εδώ αργότερα
    // - save user to DB
    // - mark as Early Access
    // - send welcome email
    console.log("✅ LemonSqueezy order:", {
      email,
      productName,
      total,
    });

    return NextResponse.json({ success: true });
  } catch (err) {
    console.error("Webhook error:", err);
    return NextResponse.json(
      { error: "Webhook handler failed" },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";

/*
  Αρχιτεκτονική:
  - source language: auto
  - target languages: όσα στείλει ο client
  - έτοιμο για 2.000+ (backend)
*/

export async function POST(req: Request) {
  try {
    const { text, targets } = await req.json();

    if (!text || !Array.isArray(targets) || targets.length === 0) {
      return NextResponse.json({ translations: {} });
    }

    // ΠΡΟΣΩΡΙΝΗ ΣΤΑΘΕΡΗ ΛΟΓΙΚΗ (demo-safe)
    // Εδώ αντικαθίσταται με DeepL / OpenAI / Google
    const translations: Record<string, string> = {};

    for (const lang of targets) {
      translations[lang] = `[${lang.toUpperCase()}] ${text}`;
    }

    return NextResponse.json({ translations });
  } catch (e) {
    return NextResponse.json(
      { error: "Translation error" },
      { status: 500 }
    );
  }
}

