/* GLOBAL BASE */

:root {
  --pv-bg: #02030a;
  --pv-bg-soft: #050718;
  --pv-gold: #f5d68a;
  --pv-gold-soft: rgba(245, 214, 138, 0.25);
  --pv-blue: #4ea4ff;
  --pv-text: #f9fafb;
  --pv-muted: #9ca3af;
  --pv-border: rgba(148, 163, 184, 0.35);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html,
body {
  padding: 0;
  margin: 0;
}

body {
  min-height: 100vh;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI",
    sans-serif;
  background: radial-gradient(circle at top, #111827 0, #02030a 55%, #000000 100%);
  color: var(--pv-text);
}

/* SHELL (συνολικό πλαίσιο) */

.shell {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  padding: 1.5rem 1.5rem 1.2rem;
}

/* TOPBAR */

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-radius: 999px;
  padding: 0.6rem 1.2rem;
  background: linear-gradient(
    90deg,
    rgba(15, 23, 42, 0.96),
    rgba(2, 6, 23, 0.98)
  );
  border: 1px solid var(--pv-border);
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.7);
  margin-bottom: 1.5rem;
}

.brand {
  display: flex;
  align-items: baseline;
  gap: 0.25rem;
}

.brand-main {
  font-weight: 700;
  font-size: 1.1rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.brand-sub {
  font-weight: 600;
  font-size: 0.9rem;
  color: var(--pv-gold);
}

.nav {
  display: flex;
  gap: 0.7rem;
  flex-wrap: wrap;
}

.nav-link {
  font-size: 0.82rem;
  font-weight: 500;
  text-decoration: none;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--pv-muted);
  padding: 0.25rem 0.55rem;
  border-radius: 999px;
  border: 1px solid transparent;
  transition: all 0.16s ease-out;
}

.nav-link:hover {
  color: var(--pv-text);
  border-color: var(--pv-gold-soft);
}

/* PAGE WRAPPER */

.page {
  flex: 1;
  display: flex;
  justify-content: center;
  padding: 0.5rem 0 1.2rem;
}

/* FOOTER */

.footer {
  font-size: 0.75rem;
  color: var(--pv-muted);
  text-align: center;
  margin-top: 0.2rem;
}

/* HOME PAGE */

.home {
  width: 100%;
  max-width: 1100px;
  background: linear-gradient(
    180deg,
    rgba(15, 23, 42, 0.96),
    rgba(3, 7, 18, 0.98)
  );
  border-radius: 24px;
  border: 1px solid var(--pv-border);
  box-shadow: 0 24px 80px rgba(0, 0, 0, 0.85);
  padding: 2.5rem 2.3rem 2rem;
}

/* μικρότερες οθόνες */
@media (max-width: 768px) {
