  border: 1px solid transparent;
  transition: all 0.16s ease-out;
}

.btn-main {
  background: linear-gradient(135deg, var(--pv-gold), #eabf63);
  color: #111827;
  box-shadow: 0 0 26px rgba(245, 214, 138, 0.4);
