/* MODULES */

.modules {
  margin-bottom: 1.9rem;
}

.section-title {
  font-size: 1.3rem;
  text-align: center;
  text-transform: uppercase;
  letter-spacing: 0.22em;
  margin-bottom: 0.7rem;
}

.section-subtitle {
  max-width: 780px;
  margin: 0 auto 1.7rem;
  text-align: center;
  font-size: 0.94rem;
  color: var(--pv-muted);
}

.modules-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1.1rem;
}

