    grid-template-columns: 1fr;
  }
}

.module-card {
  border-radius: 18px;
  border: 1px solid var(--pv-border);
  background: radial-gradient(
    circle at top left,
    rgba(15, 23, 42, 0.95),
    rgba(2, 6, 23, 0.98)
