  padding: 1.1rem 1.1rem 1rem;
  min-height: 150px;
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
}

.module-card h3 {
  margin: 0;
  font-size: 1rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--pv-gold);
}

.module-card p {
  margin: 0;
  font-size: 0.9rem;
  line-height: 1.55;
  color: var(--pv-muted);
}

.card-link {
  margin-top: 0.6rem;
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--pv-blue);
  text-decoration: none;
}

.card-link:hover {
  text-decoration: underline;
}

/* BOTTOM NOTE */

.bottom-note {
  border-top: 1px solid var(--pv-border);
  padding-top: 1.1rem;
  font-size: 0.85rem;
  color: var(--pv-muted);
  text-align: center;
}

"use client";

import {
  createContext,
  useContext,
  useState,
  type ReactNode,
} from "react";

type ChatDockContextValue = {
  isOpen: boolean;
  toggle: () => void;
};

const ChatDockContext = createContext<ChatDockContextValue | undefined>(
  undefined
);

export function ChatDockProvider({ children }: { children: ReactNode }) {
  const [isOpen, setIsOpen] = useState(false);

  const toggle = () => setIsOpen((prev) => !prev);

  return (
    <ChatDockContext.Provider value={{ isOpen, toggle }}>
      {children}
    </ChatDockContext.Provider>
  );
}

export function useChatDock() {
  const ctx = useContext(ChatDockContext);

  if (!ctx) {
    throw new Error("useChatDock must be used within ChatDockProvider");
  }

  return ctx;
}

"use client";

import {
  createContext,
  useContext,
  useState,
  type ReactNode,
  useMemo,
} from "react";

export type ConversationPreview = {
  id: string;
  title: string;
  lastMessage: string;
  unread: number;
};

type ChatDockContextType = {
  conversations: ConversationPreview[];
  isOpen: boolean;
  openConversationId: string | null;
  toggleDock: () => void;
  openConversation: (id: string) => void;
  markAsRead: (id: string) => void;
};

const ChatDockContext = createContext<ChatDockContextType | undefined>(
  undefined
);

const initialConversations: ConversationPreview[] = [
  {
    id: "1",
    title: "Ομάδα Φίλων",
    lastMessage: "Τα λέμε σε λίγο 🙂",
    unread: 2,
  },
  {
    id: "2",
    title: "Work · Έργο Νερού",
    lastMessage: "Έστειλα το νέο σχέδιο.",
    unread: 1,
  },
  {
    id: "3",
    title: "Pantavion One",
    lastMessage: "Here We Are One. For All Humanity.",
    unread: 0,
  },
];

export function ChatDockProvider({ children }: { children: ReactNode }) {
  const [isOpen, setIsOpen] = useState(false);
  const [openConversationId, setOpenConversationId] = useState<string | null>(
    null
  );
  const [conversations, setConversations] =
    useState<ConversationPreview[]>(initialConversations);

  const toggleDock = () => setIsOpen((prev) => !prev);

  const openConversation = (id: string) => {
    setIsOpen(true);
    setOpenConversationId(id);
    setConversations((prev) =>
      prev.map((c) => (c.id === id ? { ...c, unread: 0 } : c))
    );
  };

  const markAsRead = (id: string) => {
    setConversations((prev) =>
      prev.map((c) => (c.id === id ? { ...c, unread: 0 } : c))
    );
  };

  const value = useMemo(
    () => ({
      conversations,
      isOpen,
      openConversationId,
      toggleDock,
      openConversation,
      markAsRead,
    }),
    [conversations, isOpen, openConversationId]
  );

  return (
    <ChatDockContext.Provider value={value}>
      {children}
    </ChatDockContext.Provider>
  );
}

export function useChatDock() {
  const ctx = useContext(ChatDockContext);
  if (!ctx) {
    throw new Error("useChatDock must be used within ChatDockProvider");
  }
  return ctx;
}

'use client';

import React from 'react';
import {
  ChatDockProvider,
  useChatDock,
} from '../components/chat/ChatDockContext';

function ChatDock() {
  const {
    conversations,
    openConversationIds,
    isCollapsed,
    toggleCollapsed,
    toggleConversation,
    markAsRead,
  } = useChatDock();

  const totalUnread = conversations.reduce(
    (sum, c) => sum + c.unread,
    0
  );

  if (isCollapsed) {
    return (
      <div className="fixed bottom-4 right-4 rounded-2xl bg-slate-900/90 px-4 py-2 text-sm cursor-pointer border border-slate-700 shadow-lg"
           onClick={toggleCollapsed}>
        Άνοιξε Chat · {totalUnread} νέα μηνύματα
      </div>
    );
  }

  return (
    <div className="mt-8 max-w-3xl mx-auto">
      <div className="flex items-center justify-between mb-4">
        <h2 className="text-xl font-semibold">
          Συζητήσεις Pantavion
        </h2>
        <button
          onClick={toggleCollapsed}
          className="text-xs border border-slate-600 rounded-full px-3 py-1 hover:bg-slate-800"
        >
          Μείωσε
        </button>
      </div>

      <div className="grid gap-3">
        {conversations.map((conv) => (
          <button
            key={conv.id}
            onClick={() => {
              toggleConversation(conv.id);
              markAsRead(conv.id);
            }}
            className="flex items-center justify-between rounded-xl border border-slate-700 bg-slate-900/70 px-4 py-3 text-left hover:bg-slate-800"
          >
            <div>
              <div className="font-medium">{conv.title}</div>
              <div className="text-xs text-slate-400">
                {conv.lastMessage}
              </div>
            </div>
            {conv.unread > 0 && (
              <span className="ml-3 rounded-full bg-amber-500 px-2 py-1 text-[11px] font-semibold">
                {conv.unread}
              </span>
            )}
          </button>
        ))}
      </div>

      {openConversationIds.length === 0 && (
        <p className="mt-6 text-sm text-slate-400">
          Επίλεξε μια συζήτηση για να ανοίξει το παράθυρο μηνυμάτων.
        </p>
      )}
    </div>
  );
}

export default function ChatPage() {
  return (
    <ChatDockProvider>
      <main className="min-h-screen bg-slate-950 text-slate-50 px-4">
        <section className="max-w-5xl mx-auto pt-16 pb-12">
          <p className="text-xs tracking-[0.3em] uppercase text-amber-400 mb-2">
            Pantavion One · Chat
          </p>
          <h1 className="text-3xl md:text-4xl font-semibold mb-3">
            Συζητήσεις, ομάδες, συνεργασίες.
          </h1>
          <p className="text-sm md:text-base text-slate-300 max-w-2xl">
            Ενιαίο σύστημα μηνυμάτων για φίλους, ομάδες έργου, κοινότητες
            και AI βοηθούς — πλήρως συνδεδεμένο με όλα τα modules του
            Pantavion One.
          </p>

          <ChatDock />
        </section>
      </main>
    </ChatDockProvider>
  );
}
